"""Attribuering: kolliderar Calyx egen kolumntitel vid 320 px, utan K3 inblandat?"""
import asyncio, json
from playwright.async_api import async_playwright

OUT = "tests/alunix-r8/runs/K3/shots/r3/p001-calyx-bare-320.png"


async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width": 320, "height": 400})
        await pg.goto("http://127.0.0.1:3302/sites/calyx.html", wait_until="networkidle")
        await pg.wait_for_timeout(1500)
        await pg.screenshot(path=OUT)
        r = await pg.evaluate("""() => {
          const out = [];
          document.querySelectorAll('header *, nav *').forEach(function (e) {
            const t = (e.textContent || '').trim();
            if (!t || e.children.length) return;
            const b = e.getBoundingClientRect();
            if (b.width) out.push({t: t.slice(0, 24), x: Math.round(b.left), y: Math.round(b.top),
                                   r: Math.round(b.right), bo: Math.round(b.bottom)});
          });
          const hits = [];
          for (let i = 0; i < out.length; i++)
            for (let j = i + 1; j < out.length; j++) {
              const a = out[i], c = out[j];
              if (a.x < c.r && c.x < a.r && a.y < c.bo && c.y < a.bo)
                hits.push([a.t, c.t]);
            }
          return {boxes: out.length, overlaps: hits.slice(0, 8), clientW: document.documentElement.clientWidth};
        }""")
        print(json.dumps(r, indent=1))
        print("skrev", OUT)
        await b.close()

asyncio.run(main())

