import asyncio, json, sys
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:3302/tests/alunix-r8/runs/K3/index.html?preview=filled"
LOCKED = "Exempelsida: Calyx, florist i Stockholm"


async def one(b, w, h):
    pg = await b.new_page(viewport={"width": w, "height": h})
    await pg.goto(URL, wait_until="networkidle")
    await pg.wait_for_timeout(1500)
    r = await pg.evaluate("""(locked) => {
      const t = document.getElementById('c-calyx');
      const bb = t.getBBox();
      const box = t.getBoundingClientRect();
      const svg = document.getElementById('drawing');
      const vb = svg.getAttribute('viewBox').split(' ').map(Number);
      return {
        text_exact: t.textContent === locked,
        text: t.textContent,
        viewBox_w: vb[2],
        bbox_x: Math.round(bb.x * 100) / 100,
        bbox_w_units: Math.round(bb.width * 100) / 100,
        right_edge_units: Math.round((bb.x + bb.width) * 100) / 100,
        rendered_px: Math.round(box.width * 10) / 10,
        textLength: t.getAttribute('textLength'),
        lengthAdjust: t.getAttribute('lengthAdjust'),
        font: getComputedStyle(t).fontFamily
      };
    }""", LOCKED)
    await pg.close()
    return r


async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        out = {}
        for w, h in ((390, 844), (320, 568), (1440, 900)):
            out[f"{w}x{h}"] = await one(b, w, h)
        print(json.dumps(out, indent=1, ensure_ascii=False))
        await b.close()

asyncio.run(main())

