plus luft till arkets overkant och till #page-outline. Allt i user units."""
import asyncio, json
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:3302/tests/alunix-r8/runs/K3/index.html?preview=drawn"


async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width": 1440, "height": 900})
        await pg.goto(URL, wait_until="networkidle")
        await pg.wait_for_timeout(1500)
        r = await pg.evaluate("""() => {
          const t = document.getElementById('c-169').getBBox();
          // Snittbenets hogra ande: (1392, 220). Markern ar 9 lang, 6 bred,
          // refX 9, orient auto-start-reverse => pekar nedat, sa spetsens ram
          // stracker sig 9 units UPP fran 220 och 3 units at var sida om 1392.
          const arrow = {x: 1392 - 3, y: 220 - 9, w: 6, h: 9};
          const gapY = arrow.y - (t.y + t.height);      // lodratt glapp
          const overlapX = !(t.x + t.width < arrow.x || arrow.x + arrow.w < t.x);
          return {
            c169: {x: +t.x.toFixed(2), y: +t.y.toFixed(2),
                   w: +t.width.toFixed(2), h: +t.height.toFixed(2),
                   bottom: +(t.y + t.height).toFixed(2)},
            arrow_box: arrow,
            x_overlappar: overlapX,
            lodratt_glapp_units: +gapY.toFixed(2),
            luft_till_arkets_overkant: +t.y.toFixed(2),
            luft_till_page_outline_top: +(t.y - 0.75).toFixed(2),
            rit_fonster: getComputedStyle(document.getElementById('c-169')).getPropertyValue('--t'),
            markers: document.querySelectorAll('marker').length
          };
        }""")
        print(json.dumps(r, indent=1))
        await b.close()

asyncio.run(main())

