"""Plan 005-verifiering: titelblockets ruta, tomrumsandel, kollisioner."""
import asyncio, json, sys
from playwright.async_api import async_playwright

BASE = "http://127.0.0.1:3302/tests/alunix-r8/runs/K3/index.html"


async def one(b, w, h, q):
    pg = await b.new_page(viewport={"width": w, "height": h})
    await pg.goto(BASE + q, wait_until="networkidle")
    await pg.wait_for_timeout(1400)
    r = await pg.evaluate("""() => {
      const svg = document.getElementById('drawing');
      const vb = svg.getAttribute('viewBox').split(' ').map(Number);
      const bx = function (id) {
        const e = document.getElementById(id);
        if (!e || getComputedStyle(e).display === 'none') return null;
        const b = e.getBBox();
        return {x: +b.x.toFixed(1), y: +b.y.toFixed(1),
                r: +(b.x + b.width).toFixed(1), b: +(b.y + b.height).toFixed(1)};
      };
      const ids = ['title-frame', 't1', 't2', 't3', 'm-320', 'm-768', 'm-1440',
                   'c-calyx', 'c-fold', 'dim-width', 'opening'];
      const boxes = {};
      ids.forEach(function (i) { boxes[i] = bx(i); });
      const hit = [];
      const keys = Object.keys(boxes).filter(function (k) { return boxes[k]; });
      for (let i = 0; i < keys.length; i++)
        for (let j = i + 1; j < keys.length; j++) {
          const a = boxes[keys[i]], c = boxes[keys[j]];
          if (a.x < c.r && c.x < a.r && a.y < c.b && c.y < a.b) hit.push(keys[i] + ' x ' + keys[j]);
        }
      const tf = boxes['title-frame'];
      return {
        viewBox: vb, boxes: boxes, kollisioner: hit,
        tomrum_ovanfor_blocket_pct: tf ? +((tf.y / vb[3]) * 100).toFixed(1) : null,
        marginal_hoger: tf ? +(vb[2] - tf.r).toFixed(1) : null,
        marginal_botten: tf ? +(vb[3] - tf.b).toFixed(1) : null,
        stroke: tf ? getComputedStyle(document.getElementById('title-frame')).strokeWidth : null,
        fill: tf ? getComputedStyle(document.getElementById('title-frame')).fill : null
      };
    }""")
    await pg.close()
    return r


async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        out = {}
        out["390 sheet"] = await one(b, 390, 844, "?preview=sheet")
        out["390 drawn"] = await one(b, 390, 844, "?preview=drawn")
        out["320 sheet"] = await one(b, 320, 568, "?preview=sheet")
        out["1440 sheet"] = await one(b, 1440, 900, "?preview=sheet")
        print(json.dumps(out, indent=1))
        await b.close()

asyncio.run(main())

