"""Ar legendens rader tva rader TEXT, eller en symbol plus en rad text?
Gate 49 handlar om klickbar TEXT som bryts, inte om ett tvadelat block."""
import asyncio, json
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:3302/tests/alunix-r8/runs/K3/index.html"


async def one(b, w, h):
    pg = await b.new_page(viewport={"width": w, "height": h})
    await pg.goto(URL, wait_until="networkidle")
    await pg.wait_for_timeout(1200)
    r = await pg.evaluate("""() => {
      const out = [];
      document.querySelectorAll('.legend__row, .skip').forEach(function (a) {
        // Rakna radlador for enbart TEXTnoderna, inte for svg-symbolen.
        const rng = document.createRange();
        let lines = 0, txt = '';
        a.childNodes.forEach(function (n) {
          if (n.nodeType === 3 && n.textContent.trim()) {
            rng.selectNodeContents(n);
            lines += rng.getClientRects().length;
            txt += n.textContent.trim();
          }
        });
        const box = a.getBoundingClientRect();
        out.push({el: a.className, text: txt, textrader: lines,
                  bredd: Math.round(box.width), hojd: Math.round(box.height)});
      });
      return out;
    }""")
    await pg.close()
    return r


async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        for w, h in ((1440, 900), (390, 844), (320, 568)):
            print(w, "x", h, json.dumps(await one(b, w, h), ensure_ascii=False))
        await b.close()

asyncio.run(main())

